  `actual_refund_price` double(20,2) DEFAULT NULL COMMENT '实际退款金额',
  `after_sale_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '评价图片',
