  `sku_id` bigint DEFAULT NULL COMMENT '货品ID',
  PRIMARY KEY (`id`),
  KEY `member_id` (`member_id`) USING BTREE COMMENT '会员id索引',
  KEY `store_id` (`store_id`) USING BTREE COMMENT '店铺id索引'
